import { getLogger } from '@daz-pilot/backend-utils';
import nodemailer from 'nodemailer';
import {
	SMTP_ENABLED,
	SMTP_FROM_EMAIL,
	SMTP_FROM_NAME,
	SMTP_HOST,
	SMTP_PASSWORD,
	SMTP_PORT,
	SMTP_USERNAME,
} from '../../constants/env.js';
import type { EmailRecipient } from '../../types/emailTypes.js';

const formatAddress = ({ name, emailAddress }: EmailRecipient): string | { name: string; address: string } => {
	return name ? { name, address: emailAddress } : emailAddress;
};

export const sendEmailViaSmtp = async ({
	to,
	subject,
	textBody,
	htmlBody,
	replyTo,
}: {
	to: EmailRecipient;
	subject: string;
	textBody: string;
	htmlBody: string;
	replyTo?: string;
}): Promise<void> => {
	const transporter = nodemailer.createTransport({
		host: SMTP_HOST,
		port: SMTP_PORT,
		auth: {
			user: SMTP_USERNAME,
			pass: SMTP_PASSWORD,
		},
		secure: SMTP_PORT === 465,
	});

	if (SMTP_ENABLED) {
		await transporter.sendMail({
			from: formatAddress({ name: SMTP_FROM_NAME, emailAddress: SMTP_FROM_EMAIL }),
			to: formatAddress(to),
			subject,
			text: textBody,
			html: htmlBody,
			replyTo,
		});
	} else {
		getLogger().info('SMTP is not enabled');
	}
};
